        capability: Capability::Write,
        action: crate::seed::render_response(
            "general-plan-append-action",
            "en",
            &[("plan_path", PLAN_PATH)],
        )
        .unwrap_or_default(),
        expected_evidence: format!("written plan event {}", intent.impulse_id),
        command: None,
    }];
