        id: stable_id(
            "repository_work_item_plan",
            &format!("{}:{target}", intent.impulse_id),
        ),
        mode: GeneralPlanMode::RepositoryWorkItem,
        goal: intent.source_text,
        target: target.clone(),
        content: String::new(),
